import sys
from configparser import ConfigParser
c=ConfigParser(); c['args']={}
for a in sys.argv[1:]:
    if a.startswith('--'):
        a=a[2:]
        if '=' in a:
            k,v=a.split('=',1)
            c['args'][k]=v
        else:
            c['args'][a]=True
c.write(open('parsed.ini','w'))
print('PARSED')

